Here is the commit message:
crypto: atmel-sha204a - Fix OOM ->tfm_count leak

If memory allocation fails, decrement ->tfm_count to avoid blocking
future reads.

Cc: stable@vger.kernel.org
Fixes: da001fb651b0 ("crypto: atmel-i2c - add support for SHA204A random number generator")
Signed-off-by: Thorsten Blum <thorsten.blum@linux.dev>
Signed-off-by: Herbert Xu <herbert@gondor.apana.org.au>

Here is the root cause:
The function atmel_sha204a_rng_read_nonblocking increments i2c_priv->tfm_count before attempting memory allocation. If the allocation fails, the function returns -ENOMEM without decrementing tfm_count, leaving it incremented. This prevents subsequent read operations from proceeding because they check tfm_count, causing a permanent block on future reads (i.e., a leak of the counter).

Here is the patch:

 static int atmel_sha204a_rng_read_nonblocking(struct hwrng *rng, void *data,
 					      size_t max)
 {
 	struct atmel_i2c_client_priv *i2c_priv;
 	struct atmel_i2c_work_data *work_data;

 	i2c_priv = container_of(rng, struct atmel_i2c_client_priv, hwrng);

 	/* keep maximum 1 asynchronous read in flight at any time */
 	if (!atomic_add_unless(&i2c_priv->tfm_count, 1, 1))
 		return 0;

 	if (rng->priv) {
 		work_data = (struct atmel_i2c_work_data *)rng->priv;
 		max = min(sizeof(work_data->cmd.data), max);
 		memcpy(data, &work_data->cmd.data, max);
 		rng->priv = 0;
 	} else {
 		work_data = kmalloc_obj(*work_data, GFP_ATOMIC);
-		if (!work_data)
+		if (!work_data) {
+			atomic_dec(&i2c_priv->tfm_count);
 			return -ENOMEM;
-
+		}
 		work_data->ctx = i2c_priv;
 		work_data->client = i2c_priv->client;

 		max = 0;
 	}

 	atmel_i2c_init_random_cmd(&work_data->cmd);
 	atmel_i2c_enqueue(work_data, atmel_sha204a_rng_done, rng);

 	return max;
 }



